function makeStack(){ return []; }
function push(s, v){ s.push(v); return s; }
function pop(s){ return s.length ? s.pop() : undefined; }
function peek(s){ return s.length ? s[s.length-1] : undefined; }
function evalRPN(tokens){
  var st=[];
  for(var i=0;i<tokens.length;i++){
    var t=tokens[i];
    if(t==='+'||t==='-'||t==='*'||t==='/'){
      var b=st.pop(), a=st.pop();
      if(a===undefined||b===undefined) return NaN;
      var r = t==='+'?a+b : t==='-'?a-b : t==='*'?a*b : a/b;
      st.push(r);
    } else { st.push(Number(t)); }
  }
  return st.length===1 ? st[0] : NaN;
}
var EXPORTS = { makeStack:makeStack, push:push, pop:pop, peek:peek, evalRPN:evalRPN };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StackForgePure = EXPORTS; }
